int main() {
    int f[2], i;
    char r[5], a[5];

    while (scanf("%s %s", r, a) == 2 && (r[0] != '0' || a[0] != '0')) {
        int count[256] = {0}; // Frequency array for ASCII characters
        for (i = 0; i < 4; i++) {
            count[r[i]]++;
        }
        f[0] = f[1] = 0;
        for (i = 0; i < 4; i++) {
            if (count[a[i]] > 0) {
                f[i != (strchr(r, a[i]) - r)]++;
                count[a[i]]--; // Decrement count to avoid double counting
            }
        }
        printf("%d %d\n", f[0], f[1]);
    }
}

